    @Mock
    private Method isSupportedICU;

    @BeforeEach
    public void setUp() throws NoSuchMethodException {
        Class<?> clazz = CharsetUtils.class;
        getCharsetICU = clazz.getDeclaredMethod("getCharsetICU");
        isSupportedICU = clazz.getDeclaredMethod("isSupportedICU");
        getCharsetICU.setAccessible(true);
        isSupportedICU.setAccessible(true);
    }

    @Test
    public void testCleanWithISONamePattern() throws Exception {
        when(getCharsetICU.invoke(any())).thenReturn(Charset.forName("ISO-8859-1"));
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertEquals("ISO-8859-1", CharsetUtils.clean("ISO-8859-1"));
    }

    @Test
    public void testCleanWithWINNamePattern() throws Exception {
        when(getCharsetICU.invoke(any())).thenReturn(Charset.forName("Windows-1252"));
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertEquals("Windows-1252", CharsetUtils.clean("Windows-1252"));
    }

    @Test
    public void testCleanWithCPNamePattern() throws Exception {
        when(getCharsetICU.invoke(any())).thenReturn(Charset.forName("CP1252"));
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertEquals("CP1252", CharsetUtils.clean("CP1252"));
    }

    @Test
    public void testCleanWithICUException() throws Exception {
        when(getCharsetICU.invoke(any())).thenThrow(new InvocationTargetException(new Exception()));
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertNull(CharsetUtils.clean("InvalidCharset"));
    }

    @Test
    public void testCleanInvalidCharset() throws Exception {
        when(getCharsetICU.invoke(any())).thenReturn(null);
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertNull(CharsetUtils.clean("InvalidCharset"));
    }

    @Test
    public void testCleanWithICU() throws Exception {
        when(getCharsetICU.invoke(any())).thenReturn(Charset.forName("UTF-8"));
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertEquals("UTF-8", CharsetUtils.clean("UTF-8"));
    }

    @Test
    public void testCleanValidCharset() throws Exception {
        when(getCharsetICU.invoke(any())).thenReturn(Charset.forName("UTF-8"));
        when(isSupportedICU.invoke(any())).thenReturn(true);
        assertEquals("UTF-8", CharsetUtils.clean("UTF-8"));
    }
}
